test('oversized source and interrupted snapshot never modify the SQLite destination',{skip:!enabled},async t=>{
 const {importPostgresEconomySnapshot}=await import('../src/services/migration/postgresEconomyImport.js');const {conn}=await setup(t);const db=await openSQLiteStore();t.after(()=>db.close());await conn.query(`INSERT INTO economy SELECT $1,(200000000000000000::bigint+n)::text,n,0,'{}'::jsonb FROM generate_series(1,501) n`,[g]);await assert.rejects(importPostgresEconomySnapshot(conn,db,g),{code:'MIGRATION_SOURCE_INVALID'});assert.equal(db.accountKeys('').length,0);await conn.query('DELETE FROM economy WHERE user_id <> $1',['200000000000000001']);const broken={query:async(sql,args)=>{if(sql.includes('ORDER BY user_id'))throw Error('injected network fault');return conn.query(sql,args)}};await assert.rejects(importPostgresEconomySnapshot(broken,db,g),/injected network fault/);assert.equal(db.accountKeys('').length,0);assert.equal((await conn.query('SELECT count(*)::int n FROM economy')).rows[0].n,1);
});
test('real PostgreSQL AI settings, quota, points and documents copy atomically to SQLite',{skip:!enabled},async t=>{
 const {importPostgresAIDataSnapshot}=await import('../src/services/migration/postgresAIImport.js');const {createAIStore,DEFAULT_AI}=await import('../src/services/ai/foundation.js');const {createKnowledgeStore}=await import('../src/services/ai/knowledge.js');const {createActivityStore}=await import('../src/services/ai/activities.js');const {conn}=await setup(t);const user='234567890123456789';const records=[[`ai:foundation:config:${g}`,{...DEFAULT_AI,perUserDaily:10}],[`ai:foundation:usage:u:${g}:${user}`,{day:'2026-11-12',count:3}],[`ai:activity:points:${g}:${user}`,{points:12}],[`ai:knowledge:docs:${g}`,[{id:'a'.repeat(24),name:'guide.txt',content:'hello',createdAt:'2026-01-02T00:00:00.000Z'}]]];for(const [key,value] of records)await conn.query('INSERT INTO cache_data (key,value) VALUES ($1,$2::jsonb)',[key,JSON.stringify(value)]);
 const db=await openSQLiteStore();t.after(()=>db.close());const result=await importPostgresAIDataSnapshot(conn,db,g);assert.equal(result.keys,4);assert.equal(result.migrationReady,false);const client={homeGuildId:g,db:{getStatus:()=>({isDegraded:false}),isAvailable:()=>true,db:{sqlite:db,isAvailable:()=>true}}};assert.equal((await createAIStore(client).read(g)).perUserDaily,10);assert.equal((await createKnowledgeStore(client).read(g))[0].content,'hello');assert.equal(await createActivityStore(client).points(g,user),12);await assert.rejects(importPostgresAIDataSnapshot(conn,db,g),{code:'MIGRATION_DESTINATION_CONFLICT'});
});
