 await conn.query('UPDATE cache_data SET expires_at=NULL');await conn.query('INSERT INTO temp_data VALUES ($1,\'{}\',NULL)',[`ai:extra:${g}`]);await assert.rejects(importPostgresAIDataSnapshot(conn,db,g),{code:'MIGRATION_SOURCE_LEGACY'});await conn.query('DELETE FROM temp_data');await conn.query('INSERT INTO cache_data VALUES ($1,\'{}\',NULL)',[`ai:unknown:${g}`]);await assert.rejects(importPostgresAIDataSnapshot(conn,db,g),{code:'MIGRATION_SOURCE_INVALID'});assert.equal(db.get(key),null);
