test('AI destination conflicts or an injected write failure roll back all keys',{skip:!enabled},async t=>{
 const {importPostgresAIDataSnapshot}=await import('../src/services/migration/postgresAIImport.js');const {conn}=await setup(t),db=await openSQLiteStore();t.after(()=>db.close());const key1=`ai:activity:round:${g}`,key2=`ai:chat:proactive:${g}`;await conn.query('INSERT INTO cache_data VALUES ($1,\'{"state":"closed"}\',NULL),($2,\'{"day":"2026-11-12"}\',NULL)',[key1,key2]);
 db.transaction(tx=>tx.botSet('ai:other:legacy',null,Date.now()-1000));await assert.rejects(importPostgresAIDataSnapshot(conn,db,g),{code:'MIGRATION_DESTINATION_CONFLICT'});db.transaction(tx=>tx.botDelete('ai:other:legacy'));
 const faulty={dialect:'sqlite',isOpen:()=>true,transaction:fn=>db.transaction(tx=>fn({...tx,set:(key,value)=>{if(key===key2)throw Error('injected failure');tx.set(key,value)}}))};await assert.rejects(importPostgresAIDataSnapshot(conn,faulty,g),/injected failure/);assert.equal(db.get(key1),null);assert.equal(db.get(key2),null);
});
async function createConfigTables(conn){await conn.query('CREATE TABLE guilds(id varchar(20) PRIMARY KEY, config jsonb, counters jsonb); CREATE TABLE welcome_configs(guild_id varchar(20) PRIMARY KEY, config jsonb); CREATE TABLE leveling_configs(guild_id varchar(20) PRIMARY KEY, config jsonb)');}
test('real PostgreSQL guild, welcome, leveling and counter configs copy to SQLite',{skip:!enabled},async t=>{
 const {importPostgresConfigSnapshot}=await import('../src/services/migration/postgresConfigImport.js');const {createSQLiteBotDatabase}=await import('../src/services/storage/sqliteBotDatabase.js');const {getGuildConfig}=await import('../src/services/config/guildConfig.js');const {getWelcomeConfig}=await import('../src/utils/database.js');const {conn}=await setup(t);await createConfigTables(conn);await conn.query(`INSERT INTO guilds VALUES ($1,'{"prefix":"!"}','[]')`,[g]);await conn.query(`INSERT INTO welcome_configs VALUES ($1,'{"enabled":true,"channelId":"234567890123456789"}')`,[g]);await conn.query(`INSERT INTO leveling_configs VALUES ($1,'{"enabled":true,"xpPerMessage":15}')`,[g]);const db=await openSQLiteStore();t.after(()=>db.close());const out=await importPostgresConfigSnapshot(conn,db,g);assert.equal(out.keys,4);assert.equal(out.migrationReady,false);const adapter=createSQLiteBotDatabase(db),wrapper={db:adapter,isAvailable:()=>true,getStatus:()=>({isDegraded:false}),get:(...x)=>adapter.get(...x)},c={homeGuildId:g,db:wrapper};assert.equal((await getGuildConfig(c,g)).prefix,'!');assert.equal((await getWelcomeConfig(c,g)).channelId,'234567890123456789');assert.equal((await adapter.get(`guild:${g}:leveling:config`)).xpPerMessage,15);assert.deepEqual(await adapter.get(`guild:${g}:counters`),[]);await assert.rejects(importPostgresConfigSnapshot(conn,db,g),{code:'MIGRATION_DESTINATION_CONFLICT'});
});
