test('real PostgreSQL bot key copy resolves legacy names and preserves timezone-aware TTL',{skip:!enabled},async t=>{
 const {importPostgresBotKvSnapshot}=await import('../src/services/migration/postgresBotKvImport.js');const {createSQLiteBotDatabase}=await import('../src/services/storage/sqliteBotDatabase.js');const {conn}=await setup(t),u='234567890123456789';await conn.query("SET TIME ZONE 'Asia/Jakarta'");
 await conn.query('INSERT INTO temp_data VALUES ($1,$2::jsonb,NULL)',[`moderation:warnings:${g}:${u}`,'[{"id":1,"reason":"test"}]']);await conn.query('INSERT INTO temp_data VALUES ($1,$2::jsonb,$3::timestamp)',[`moderation_user_notes_list_${g}`,'["note"]','2020-01-01 12:00:00']);await conn.query('INSERT INTO temp_data VALUES ($1,$2::jsonb,NULL)',[`moderation_cases_list_${g}`,'[]']);await conn.query('INSERT INTO temp_data VALUES ($1,$2::jsonb,NULL)',[`guild:${g}:ticket:counter`,'9']);await conn.query("INSERT INTO temp_data VALUES ('__meta:key_migration:v1','{}',NULL)");await conn.query('INSERT INTO cache_data VALUES ($1,$2::jsonb,$3::timestamp)',[`cache:${g}:lookup`,'{"value":"hello"}','2031-01-01 12:00:00']);await conn.query('INSERT INTO cache_data VALUES ($1,\'{}\',NULL)',[`ai:foundation:config:${g}`]);
 const db=await openSQLiteStore();t.after(()=>db.close());const result=await importPostgresBotKvSnapshot(conn,db,g);assert.equal(result.keys,5);assert.equal(result.migrationReady,false);const adapter=createSQLiteBotDatabase(db),canonical=`guild:${g}:warnings:${u}`;assert.deepEqual(await adapter.get(canonical),[{id:1,reason:'test'}]);assert.deepEqual(await adapter.get(`moderation:warnings:${g}:${u}`),[{id:1,reason:'test'}]);assert.equal(await adapter.get(`guild:${g}:usernotes:list`),null);assert.equal(await adapter.get(`guild:${g}:ticket:counter`),9);assert.deepEqual(await adapter.get(`cache:${g}:lookup`),{value:'hello'});db.transaction(tx=>{assert.equal(tx.botGetRaw(canonical).expiresAt,null);assert.equal(tx.botGetRaw(`cache:${g}:lookup`).expiresAt,Date.parse('2031-01-01T12:00:00+07:00')); assert.equal(tx.botGetRaw(`guild:${g}:usernotes:list`).expiresAt,Date.parse('2020-01-01T12:00:00+07:00'));});assert.equal(db.get(`ai:foundation:config:${g}`),null);await assert.rejects(importPostgresBotKvSnapshot(conn,db,g),{code:'MIGRATION_DESTINATION_CONFLICT'});
});
